export class AdminChangeControl implements OnInit, OnDestroy {
  readonly auth = inject(AuthService);
  readonly icons = { arrow: ArrowRight16, check: CheckmarkFilled16, warning: WarningAltFilled16, pending: Pending16, commit: Commit16, renew: Renew16 };
  readonly activeTab = signal<'overview' | 'journey' | 'repositories' | 'changes' | 'approval' | 'webhooks' | 'supply-chain' | 'dr-contracts'>('overview');
  readonly state = signal<ChangeControlState | null>(null); readonly down = signal(''); readonly busy = signal(false); readonly submitting = signal(false); readonly approving = signal(''); readonly retrying = signal(''); readonly message = signal<{ type: 'danger' | 'success' | 'warning' | 'info'; text: string } | null>(null);
  readonly approvalTarget = signal<ChangeRequest | null>(null); readonly approvalError = signal('');
  readonly retryTarget = signal<ChangeRequest | null>(null); readonly retryError = signal('');
  readonly requestedTemplate = signal<ChangeTemplate | null>(null);
  readonly draft = signal({ consumerId: 'extensions', action: 'configure', target: 'extensions', reason: '', desiredState: '{\n  "enabled": true\n}' }); readonly managementReady = computed(() => this.state()?.managementReady ?? false);
  private readonly http = inject(HttpService); private readonly route = inject(ActivatedRoute); private timer: ReturnType<typeof setInterval> | null = null;
  async ngOnInit(): Promise<void> { await this.loadRequestedTemplate(); await this.refresh(); this.timer = setInterval(() => void this.refresh(true), 20_000); }
  ngOnDestroy(): void { if (this.timer) clearInterval(this.timer); }
  shortId(value: string | null | undefined): string { return String(value || '').slice(0, 12); } join(value: string[] | null | undefined): string { return (value || []).join(', '); } isPending(status: string): boolean { return ['intent', 'authorized', 'committed'].includes(status); } inFlight(value: ChangeControlState): number { return (value.byStatus['intent'] || 0) + (value.byStatus['authorized'] || 0) + (value.byStatus['committed'] || 0); } inputValue(event: Event): string { return (event.target as HTMLInputElement | HTMLTextAreaElement).value; } selectValue(event: Event): string { return (event.target as HTMLSelectElement).value; }
  formatDate(value: string | null | undefined): string { if (!value) return '기록 없음'; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value) : new Intl.DateTimeFormat('ko-KR', { timeZone: 'Asia/Seoul', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(date) + ' KST'; }
  statusClass(value: string | null | undefined): string { const normalized = String(value || '').toLowerCase(); if (/failed|unavailable|missing|allowed/.test(normalized)) return 'status-label danger'; if (/attention|insufficient|incomplete/.test(normalized)) return 'status-label warn'; if (/awaiting|pending|authorized|committed/.test(normalized)) return 'status-label waiting'; if (/notconfigured|not configured|unknown|not queued/.test(normalized)) return 'status-label neutral'; return 'status-label ok'; }
  approvedCount(value: ChangeControlState): number { return value.changes.reduce((total, change) => total + change.approvals.filter((approval) => approval.status === 'applied').length, 0); }
  boundContractCount(value: ChangeControlState): number { return value.contracts.filter((contract) => contract.observability?.phase === 'Bound').length; }
  evidenceCoverage(value: ChangeControlState): string { const policy = value.supplyChain; const policyChecks = policy ? [policy.protected, !policy.directPushEnabled, policy.signedCommitsRequired, policy.requiredApprovals >= 1, policy.blockRejectedReviews].filter(Boolean).length : 0; return `${policyChecks}/5 policy gates · ${value.receipts.length} receipts`; }
  nextAction(value: ChangeControlState): string { if (!value.ready) return '선언 저장소 연결 복구'; if (!value.managementReady) return '서비스 토큰 / webhook secret 확인'; if (!value.changes.length) return '첫 상태 변경 요청 생성'; const latest = value.changes[0]; return this.changeNextAction(latest); }
  changeVerdict(change: ChangeRequest): string { if (change.status === 'failed' || change.execution?.last_error || change.outbox?.last_error) return 'Failed'; if (change.status === 'applied' && change.k8s_operation_id) return 'Observed'; if (['committed', 'authorized'].includes(change.status) || /await|pending|queued/i.test(change.execution?.reconciler_status || change.outbox?.status || '')) return 'Awaiting consumer'; return change.status === 'intent' ? 'Attention required' : 'Awaiting consumer'; }
  actionLabel(action: string): string { const normalized = String(action || '').replace(/^[a-z0-9_-]+:/i, '').toLowerCase(); return ({ configure: '구성 변경', apply: '변경 적용', rollback: '변경 되돌리기' } as Record<string, string>)[normalized] || normalized || '변경'; }
  changeVerdictLabel(change: ChangeRequest): string { return ({ Failed: '조치 필요', Observed: '배포 결과 확인됨', 'Awaiting consumer': '진행 중', 'Attention required': '확인 필요' } as Record<string, string>)[this.changeVerdict(change)] || '상태 확인 필요'; }
  changeSummary(change: ChangeRequest): string { const verdict = this.changeVerdict(change); if (verdict === 'Failed') return '배포 과정에서 문제가 확인되었습니다. 아래의 실패 단계와 오류 정보를 확인한 뒤 재적용을 요청하세요.'; if (verdict === 'Observed') return '변경이 반영되고 실제 상태 확인 기록까지 남았습니다. 선언한 값과 실제 상태가 같은지 마지막으로 확인하세요.'; if (!change.execution?.pull_number) return '변경 요청을 기록했습니다. 검토할 변경 내용(PR)을 준비하는 중입니다.'; if (!this.isApprovalApplied(change)) return this.isOwnerMfa(change) ? '변경 내용이 준비되었습니다. 최고 관리자의 최근 MFA 승인과 자동 병합을 처리하고 있습니다.' : '변경 내용이 준비되었습니다. 요청자와 다른 운영자의 검토 및 승인을 기다리고 있습니다.'; if (!change.execution?.merge_revision) return '승인은 완료되었습니다. 보호된 브랜치에 변경을 반영하는 중입니다.'; return '변경을 배포 작업에 전달했습니다. 실제 환경 반영 결과를 확인하는 중입니다.'; }
  changeNextAction(change: ChangeRequest): string { const verdict = this.changeVerdict(change); if (verdict === 'Failed') return '오류 원인을 확인한 뒤 재적용 요청'; if (verdict === 'Observed') return '선언한 값과 실제 상태에 차이가 없는지 최종 확인'; if (!change.execution?.pull_number) return '검토할 변경 내용(PR) 생성 확인'; if (!this.isApprovalApplied(change)) return this.isOwnerMfa(change) ? '최고 관리자 MFA 자동 승인 결과 확인' : '다른 운영자의 검토 및 승인'; if (!change.execution?.merge_revision) return '보호된 브랜치 반영 확인'; return '배포 작업과 실제 상태 확인 결과 대기'; }
  journeyStepStateLabel(state: JourneyItem['state']): string { return ({ done: '완료', waiting: '대기', failed: '실패' } as Record<JourneyItem['state'], string>)[state]; }
  outboxStatusLabel(status: string | null | undefined): string { return ({ sent: '배포 담당(소비자 적용기)에 전달 완료', delivered: '배포 담당(소비자 적용기)에 전달 완료', completed: '배포 담당(소비자 적용기)이 처리 완료', queued: '배포 담당(소비자 적용기) 대기', pending: '배포 담당(소비자 적용기) 대기' } as Record<string, string>)[String(status || '').toLowerCase()] || (status ? `배포 작업 ${status}` : '배포 담당(소비자 적용기) 대기'); }
  approvalStatusLabel(status: string): string { return ({ intent: '승인 기록 중', applied: '승인 완료', failed: '승인 실패' } as Record<string, string>)[status] || '승인 상태 확인 필요'; }
  approvalStatusClass(status: string): string { return `approval-entry ${status === 'applied' ? 'done' : status === 'failed' ? 'failed' : 'waiting'}`; }
  completedApprovalCount(change: ChangeRequest): number { return change.approvals.filter((approval) => approval.status === 'applied').length; }
  journeyFor(change: ChangeRequest): JourneyItem[] { const approved = this.isApprovalApplied(change); const merged = Boolean(change.execution?.merge_revision || change.git_commit_sha); const outboxDone = /sent|delivered|completed/i.test(change.outbox?.status || ''); const failed = this.changeVerdict(change) === 'Failed'; const required = this.state()?.supplyChain?.requiredApprovals || 1; const ownerMfa = this.isOwnerMfa(change); return [
    { key: 'intent', label: '변경 요청 접수', evidence: this.formatDate(change.created_at), detail: '변경 사유와 대상이 감사 기록에 저장됨', state: 'done' },
    { key: 'audit', label: '감사 기록 연결', evidence: '요청 기록 보관', detail: '요청·승인·배포 결과를 같은 변경으로 추적', state: 'done' },
    { key: 'pr', label: '변경 내용 확정', evidence: change.execution?.pull_number ? `PR #${change.execution.pull_number}` : '준비 중', detail: change.execution?.pull_number ? '검토 가능한 변경 내용이 생성됨' : '검토할 변경 내용을 만드는 중', state: change.execution?.pull_number ? 'done' : 'waiting' },
    { key: 'approval', label: ownerMfa ? '최고 관리자 MFA 승인' : '다른 운영자 승인', evidence: ownerMfa ? `${this.completedApprovalCount(change)}건 기록` : `${this.completedApprovalCount(change)}/${required}명 완료`, detail: approved ? this.approvalActorLabel(change) : (ownerMfa ? '최근 AAL2와 사유를 검증하는 중' : '요청자와 다른 운영자의 검토를 기다리는 중'), state: approved ? 'done' : (failed ? 'failed' : 'waiting') },
    { key: 'merge', label: '보호된 변경 반영', evidence: merged ? '반영 완료' : '반영 대기', detail: merged ? '승인된 변경만 보호된 브랜치에 반영됨' : '승인 및 병합 조건을 확인하는 중', state: merged ? 'done' : 'waiting' },
    { key: 'outbox', label: '배포 작업 전달', evidence: this.outboxStatusLabel(change.outbox?.status), detail: outboxDone ? '배포 작업이 적용기로 전달됨' : '적용기에 전달할 작업을 준비하는 중', state: failed ? 'failed' : (outboxDone ? 'done' : 'waiting') },
    { key: 'observed', label: '배포 결과 확인', evidence: change.k8s_operation_id ? '확인 기록 있음' : '결과 대기', detail: change.k8s_operation_id ? '실제 환경의 상태 확인 기록이 연결됨' : '실제 환경 반영 결과를 기다리는 중', state: failed ? 'failed' : (change.status === 'applied' && change.k8s_operation_id ? 'done' : 'waiting') },
  ]; }
  recoveryVerdict(unit: RecoveryUnit): string { if (/attention|insufficient|failed|unknown/i.test(unit.state)) return 'Attention required'; if (unit.checks?.some((check) => check.verdict !== 'Verified')) return 'Attention required'; if (unit.assertions.some((assertion) => /^(users|repositories)=0$/i.test(assertion.trim()))) return 'Attention required'; return unit.state === 'Verified' ? 'Verified' : unit.state; }
  setDraft(key: 'consumerId' | 'action' | 'target' | 'reason' | 'desiredState', value: string): void { this.draft.update((draft) => ({ ...draft, [key]: value, ...(key === 'consumerId' && draft.target === 'extensions' ? { target: value } : {}) })); }
  isOwnerMfa(change: ChangeRequest): boolean { return change.approvalPolicy === 'owner-mfa'; }
  approvalPolicyLabel(change: ChangeRequest): string { return this.isOwnerMfa(change) ? '최고 관리자 MFA' : `교차 승인 ${this.state()?.supplyChain?.requiredApprovals || 1}명 필요`; }
  isApprovalApplied(change: ChangeRequest): boolean { return change.approvals.some((approval) => approval.status === 'applied'); }
  requesterLabel(change: ChangeRequest): string { return change.requester?.displayName || change.actor_id || '요청자 미상'; }
  approvalActorLabel(change: ChangeRequest): string { const latest = change.approvals[change.approvals.length - 1]; if (!latest) return '승인자 미배정'; return `${latest.approver_display_name || this.shortId(latest.approver_id)} · ${this.formatDate(latest.completed_at || latest.created_at)}`; }
  approvalLabel(change: ChangeRequest): string { const latest = change.approvals[change.approvals.length - 1]; if (!latest) return this.isOwnerMfa(change) ? '최고 관리자 MFA 승인 대기' : '교차 승인 대기'; const result = ({ intent: '승인 기록 중', applied: '승인 완료', failed: '승인 실패' } as Record<string, string>)[latest.status] || latest.status; return this.isOwnerMfa(change) ? `최고 관리자 MFA ${result}` : `교차 ${result}`; }
  changeStatusLabel(status: string): string { return ({ intent: '요청 접수', authorized: '승인 대기', committed: '적용 대기', applied: '적용 완료', failed: '적용 실패', unknown: '상태 확인 필요' } as Record<string, string>)[status] || status; }
  approvalDialogMessage(): string { const change = this.approvalTarget(); return change ? `${this.actionLabel(change.action)} · ${change.target}\n요청자: ${this.requesterLabel(change)}\n요청 사유: ${change.reason}` : ''; }
  retryDialogMessage(): string { const change = this.retryTarget(); return change ? `${change.action} · ${change.target}\n이전 적용 실패: ${change.execution?.last_error || change.outbox?.last_error || '상세 오류 없음'}\n수정된 적용 환경에서 같은 승인·병합본을 다시 실행합니다.` : ''; }
  openApproval(change: ChangeRequest): void { this.approvalError.set(''); this.approvalTarget.set(change); }
  closeApproval(): void { if (this.approving()) return; this.approvalError.set(''); this.approvalTarget.set(null); }
  openRetry(change: ChangeRequest): void { this.retryError.set(''); this.retryTarget.set(change); }
  closeRetry(): void { if (this.retrying()) return; this.retryError.set(''); this.retryTarget.set(null); }
  async loadRequestedTemplate(): Promise<void> { const templateId = this.route.snapshot.queryParamMap.get('template'); if (!templateId) return; this.busy.set(true); try { const response = await this.http.request(`/api/platform/change-templates/${encodeURIComponent(templateId)}`, { cache: 'no-store' }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`)); const template = result as ChangeTemplate; this.requestedTemplate.set(template); this.draft.set({ consumerId: template.consumerId, action: template.action, target: template.target, reason: '', desiredState: JSON.stringify(template.desiredState, null, 2) }); this.activeTab.set('changes'); } catch (error) { this.message.set({ type: 'danger', text: `설치 요청서 로드 실패: ${String(error)}` }); } finally { this.busy.set(false); } }
  async submitChange(): Promise<void> { const draft = this.draft(); let desiredState: object; try { desiredState = JSON.parse(draft.desiredState) as object; } catch { this.message.set({ type: 'danger', text: 'Desired state는 유효한 JSON object여야 합니다.' }); return; } if (!desiredState || Array.isArray(desiredState)) { this.message.set({ type: 'danger', text: 'Desired state는 JSON object여야 합니다.' }); return; } this.submitting.set(true); try { const response = await this.http.request('/api/platform/changes', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...draft, desiredState, ...(this.requestedTemplate() ? { templateId: this.requestedTemplate()!.id } : {}) }) }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`)); this.message.set({ type: 'success', text: result.duplicate ? `기존 변경 요청 ${result.requestId}을 사용합니다.` : `서명된 상태 선언 #${result.pullRequest?.number || '—'}을 생성했습니다. 교차 운영자 승인 후 설치와 Ready 검증이 자동 실행됩니다.` }); this.activeTab.set('approval'); await this.refresh(true); } catch (error) { this.message.set({ type: 'danger', text: `변경 요청 생성 실패: ${String(error)}` }); } finally { this.submitting.set(false); } }
  async approveSelected(reason: string): Promise<void> { const change = this.approvalTarget(); if (!change) return; this.approving.set(change.request_id); this.approvalError.set(''); try { const response = await this.http.request(`/api/platform/changes/${encodeURIComponent(change.request_id)}/approve`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ reason }) }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`)); this.approvalTarget.set(null); this.message.set({ type: 'success', text: result.merged ? '교차 승인과 상태 선언 병합이 완료되었습니다. 자동 적용과 실측 결과 영수증을 기다립니다.' : '승인은 기록됐고 상태 선언 병합 결과를 확인 중입니다.' }); await this.refresh(true); } catch (error) { this.approvalError.set(`승인 또는 상태 선언 병합 실패: ${String(error)}`); } finally { this.approving.set(''); } }
  async retrySelected(reason: string): Promise<void> { const change = this.retryTarget(); if (!change) return; this.retrying.set(change.request_id); this.retryError.set(''); try { const response = await this.http.request(`/api/platform/changes/${encodeURIComponent(change.request_id)}/retry`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ reason }) }); const result = await response.json().catch(() => ({})); if (!response.ok) throw new Error(String(result.error || `HTTP ${response.status}`)); this.retryTarget.set(null); this.message.set({ type: 'success', text: '재적용 요청을 감사 이력에 기록하고 적용 대기열에 등록했습니다.' }); await this.refresh(true); } catch (error) { this.retryError.set(`재적용 요청 실패: ${String(error)}`); } finally { this.retrying.set(''); } }
  async refresh(silent = false): Promise<void> { if (!silent) this.busy.set(true); try { const response = await this.http.request('/api/platform/gitea/status', { cache: 'no-store' }); if (!response.ok) { this.down.set(`변경 관리 서비스 상태 HTTP ${response.status}`); return; } const next = await response.json() as ChangeControlState; this.state.set(next); if (!this.requestedTemplate() && next.contracts.length && !next.contracts.some((contract) => contract.consumer_id === this.draft().consumerId)) { const first = next.contracts[0]; this.draft.update((draft) => ({ ...draft, consumerId: first.consumer_id, target: first.consumer_id })); } this.down.set(''); } catch (error) { this.down.set(`변경 관리 서비스 상태 조회 실패: ${String(error)}`); } finally { if (!silent) this.busy.set(false); } }
}
